mapper.select:
SELECT
    -- 总分配资源数
    (
        SELECT COUNT(*) FROM plan_pilot_assignments WHERE plan_id = #{planId} AND status != 'CANCELLED'
        ) + (
SELECT COUNT(*) FROM plan_driver_assignments WHERE plan_id = #{planId} AND status != 'CANCELLED'
    ) + (
SELECT COUNT(*) FROM plan_tugboat_assignments WHERE plan_id = #{planId} AND status != 'CANCELLED'
    ) + (
SELECT COUNT(*) FROM plan_pilot_boat_assignments WHERE plan_id = #{planId} AND status != 'CANCELLED'
    ) + (
SELECT COUNT(*) FROM plan_vehicle_assignments WHERE plan_id = #{planId} AND status != 'CANCELLED'
    ) as total_count,

                                              -- 已确认资源数（从分配表统计CONFIRMED状态）
                                                  (
SELECT COUNT(*) FROM plan_pilot_assignments WHERE plan_id = #{planId} AND status IN ('CONFIRMED', 'COMPLETED')
    ) + (
SELECT COUNT(*) FROM plan_driver_assignments WHERE plan_id = #{planId} AND status IN ('CONFIRMED', 'COMPLETED')
    ) + (
SELECT COUNT(*) FROM plan_tugboat_assignments WHERE plan_id = #{planId} AND status IN ('CONFIRMED', 'COMPLETED')
    ) + (
SELECT COUNT(*) FROM plan_pilot_boat_assignments WHERE plan_id = #{planId} AND status IN ('CONFIRMED', 'COMPLETED')
    ) + (
SELECT COUNT(*) FROM plan_vehicle_assignments WHERE plan_id = #{planId} AND status IN ('CONFIRMED', 'COMPLETED')
    ) as confirmed_count
